 "content": "def transform(grid):
    """Fill the cavity of a broken-top rectangular frame and extend its gap."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                rr, cc = stack.pop()
                comp.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 5 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            components.append(comp)

    for comp in components:
        top = min(r for r, _ in comp)
        bottom = max(r for r, _ in comp)
        left = min(c for _, c in comp)
        right = max(c for _, c in comp)
        if bottom - top < 2 or right - left < 2:
            continue
        # The candidate is a rectangular frame: complete sides and bottom,
        # with exactly one missing cell in the top edge.
        if any(grid[r][left] != 5 or grid[r][right] != 5 for r in range(top, bottom + 1)):
            continue
        if any(grid[bottom][c] != 5 for c in range(left, right + 1)):
            continue
        gaps = [c for c in range(left + 1, right) if grid[top][c] != 5]
        if len(gaps) != 1 or any(grid[top][c] != 5 for c in (left, right)):
            continue
        gap = gaps[0]
        # Fill the enclosed cavity and the missing top-edge cell.
        out[top][gap] = 2
        for r in range(top + 1, bottom):
            for c in range(left + 1, right):
                out[r][c] = 2
        # Extend outward above the gap toward the side with the longer top
        # segment; ties use the left side for deterministic behavior.
        left_len = sum(grid[top][c] == 5 for c in range(left, gap))
        right_len = sum(grid[top][c] == 5 for c in range(gap + 1, right + 1))
        if left_len >= right_len:
            for c in range(0, gap + 1):
                out[top - 1][c] = 2
        else:
            for c in range(gap, w):
                out[top - 1][c] = 2
    return out


